import { existsSync, readFileSync } from 'node:fs';
import { join, resolve } from 'node:path';

import { describe, expect, it } from 'vitest';

/**
 * The unit gate proves the derivation; this proves the artefact, which is the only thing Google
 * reads. Both are needed for the reason sitemap-no-wizard.test.ts already records: a route can
 * vanish from the config and still be emitted, because the sitemap is generated by scanning
 * built HTML.
 *
 * describe.runIf(built) like its neighbours: this runs only against dist/, which only ci.yml
 * produces before the tests. A dist-less local run skips it, and that skip is not a pass.
 */
const dist = resolve(__dirname, '../../../dist');
const sitemapPath = join(dist, 'sitemap.xml');
const built = existsSync(dist) && existsSync(sitemapPath);

describe.runIf(built)('the sitemap does not advertise a noindexed route', () => {
  const xml = built ? readFileSync(sitemapPath, 'utf-8') : '';
  const locations = [...xml.matchAll(/<loc>([^<]*)<\/loc>/g)].map(match => match[1]);

  it('reads a sitemap with entries in it', () => {
    expect(locations.length).toBeGreaterThan(50);
  });

  for (const route of ['results', 'sample']) {
    it(`lists no /${route}, in any locale`, () => {
      const offenders = locations.filter(loc => new RegExp(`/${route}$`).test(loc));
      expect(offenders, `sitemap advertises ${offenders.join(', ')}`).toEqual([]);
    });
  }

  it('still lists the routes that should be there', () => {
    // The failure mode of an over-broad matcher is an empty sitemap, and an empty sitemap
    // satisfies every assertion above.
    for (const kept of ['https://safeunfollow.app/', 'https://safeunfollow.app/upload']) {
      expect(locations, `${kept} vanished`).toContain(kept);
    }
  });
});
